//! 🎞️ Controlled timeline, channel, keyframe and typed animation sample construction.
use super::{SemioAnimationSnapshot,AnimTimeline,AnimChannel,AnimTarget,AnimTargetProperty,AnimInterpolation,AnimKeyframe,AnimValue,SemioPoint3,SemioQuaternion,STDIO_SEMIOANIMATION_DOCUMENT_SCHEMA};
use crate::standards::v1::subsets::base::schema::snapshot::native_decoding as native;
use semio_framework_value::native_decoding::NativeDecodeControl;
use store::sqlite_snapshot::{SqliteSnapshotControl,SqliteDatabaseLimits};
pub(super) fn decode(payload:&store::os_io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<SemioAnimationSnapshot,String>{native::decode(payload,STDIO_SEMIOANIMATION_DOCUMENT_SCHEMA,control,binary,document)}
fn interpolation(tag:u8)->Result<AnimInterpolation,String>{Ok(match tag{0=>AnimInterpolation::Linear,1=>AnimInterpolation::Step,2=>AnimInterpolation::CubicSpline,_=>return Err("invalid Semio native interpolation".into())})}
fn f64(reader:&mut store::ByteReader<'_>)->Result<f64,String>{reader.read_f64_le().map_err(|error|error.to_string())}
fn value_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<AnimValue,String>{
 Ok(match reader.read_u8().map_err(|error|error.to_string())?{
 0=>{native::entities(entities,1,limits)?;AnimValue::Scalar{value:f64(reader)?}},1=>{native::entities(entities,1,limits)?;AnimValue::Vec3{value:SemioPoint3{x:f64(reader)?,y:f64(reader)?,z:f64(reader)?}}},2=>{native::entities(entities,1,limits)?;AnimValue::Quat{value:SemioQuaternion{x:f64(reader)?,y:f64(reader)?,z:f64(reader)?,w:f64(reader)?}}},
 3=>{let count=native::length(reader)?;native::entities(entities,count,limits)?;let mut values=control.allocate_vec::<f64>(count)?;control.scoped_stage(|control|{control.begin_stage(count)?;for _ in 0..count{values.push(f64(reader)?);control.step()?;}Ok::<_,String>(())})?;AnimValue::Weights{values}},_=>return Err("invalid Semio native animation value".into())})
}
pub(crate) fn binary(body:&[u8],control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioAnimationSnapshot,String>{
 let mut entities=0;native::entities(&mut entities,1,limits)?;let mut reader=store::ByteReader::new(body);if reader.read_u8().map_err(|error|error.to_string())?!=1{return Err("unsupported Semio animation native format".into())}let schema=native::text(&mut reader,control)?;let count=native::length(&mut reader)?;native::entities(&mut entities,count,limits)?;let mut timelines=control.allocate_vec::<AnimTimeline>(count)?;
 control.scoped_stage(|control|{control.begin_stage(count)?;for _ in 0..count{let name=match reader.read_u8().map_err(|error|error.to_string())?{0=>None,1=>Some(native::text(&mut reader,control)?),_=>return Err("invalid Semio native timeline name presence".into())};let count=native::length(&mut reader)?;native::entities(&mut entities,count,limits)?;let mut channels=control.allocate_vec::<AnimChannel>(count)?;
 control.scoped_stage(|control|{control.begin_stage(count)?;for _ in 0..count{let node=native::text(&mut reader,control)?;let property=match reader.read_u8().map_err(|error|error.to_string())?{0=>AnimTargetProperty::Translation,1=>AnimTargetProperty::Rotation,2=>AnimTargetProperty::Scale,3=>AnimTargetProperty::Weights,4=>AnimTargetProperty::Custom{name:native::text(&mut reader,control)?},_=>return Err("invalid Semio native target property".into())};let target=AnimTarget{node,property};let interpolation=interpolation(reader.read_u8().map_err(|error|error.to_string())?)?;let count=native::length(&mut reader)?;native::entities(&mut entities,count,limits)?;let mut keyframes=control.allocate_vec::<AnimKeyframe>(count)?;
 control.scoped_stage(|control|{control.begin_stage(count)?;for _ in 0..count{let t=f64(&mut reader)?;let value=value_binary(&mut reader,control,limits,&mut entities)?;keyframes.push(AnimKeyframe{t,value});control.step()?;}Ok::<_,String>(())})?;channels.push(AnimChannel{target,interpolation,keyframes});control.step()?;}Ok::<_,String>(())})?;timelines.push(AnimTimeline{name,channels});control.step()?;}Ok::<_,String>(())})?;
 if reader.remaining()!=0{return Err("Semio animation native trailing bytes".into())}Ok(SemioAnimationSnapshot{schema,timelines})
}
fn value_text(value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<AnimValue,String>{
 let(tag,body)=value.split_once(':').ok_or("Semio native animation value requires colon")?;Ok(match tag{
 "S"=>{native::entities(entities,1,limits)?;AnimValue::Scalar{value:native::float(body,control)?}},"V"=>{native::entities(entities,1,limits)?;let[x,y,z]=native::record(body,control)?;AnimValue::Vec3{value:SemioPoint3{x:native::float(x,control)?,y:native::float(y,control)?,z:native::float(z,control)?}}},"Q"=>{native::entities(entities,1,limits)?;let[x,y,z,w]=native::record(body,control)?;AnimValue::Quat{value:SemioQuaternion{x:native::float(x,control)?,y:native::float(y,control)?,z:native::float(z,control)?,w:native::float(w,control)?}}},
 "W"=>{let mut items=native::Items::new(body)?;let count=items.count(control,limits.max_rows)?;native::entities(entities,count,limits)?;let mut values=control.allocate_vec::<f64>(count)?;control.scoped_stage(|control|{control.begin_stage(count)?;while let Some(item)=items.next(control)?{values.push(native::float(item,control)?);control.step()?;}Ok::<_,String>(())})?;AnimValue::Weights{values}},_=>return Err("invalid Semio native animation value".into())})
}
pub(crate) fn document(body:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioAnimationSnapshot,String>{
 let mut entities=0;native::entities(&mut entities,1,limits)?;let fields=native::fields(body,["schema","timelines"],control)?;let schema=native::hex_text(fields[0].ok_or("Semio animation native schema missing")?,control)?;let mut items=native::Items::new(fields[1].unwrap_or("[]"))?;let count=items.count(control,limits.max_rows)?;native::entities(&mut entities,count,limits)?;let mut timelines=control.allocate_vec::<AnimTimeline>(count)?;
 control.scoped_stage(|control|{control.begin_stage(count)?;while let Some(item)=items.next(control)?{let[name,channel_fields]=native::record(item,control)?;let name=if name=="[0]"{None}else{let[tag,name]=native::record(name,control)?;if tag!="1"{return Err("invalid Semio native timeline name presence".into())}Some(native::hex_text(name,control)?)};let mut channel_items=native::Items::new(channel_fields)?;let count=channel_items.count(control,limits.max_rows)?;native::entities(&mut entities,count,limits)?;let mut channels=control.allocate_vec::<AnimChannel>(count)?;
 control.scoped_stage(|control|{control.begin_stage(count)?;while let Some(item)=channel_items.next(control)?{let[target,interpolation_fields,keyframe_fields]=native::record(item,control)?;let[node,property]=native::record(target,control)?;let node=native::hex_text(node,control)?;let property=match property{"t"=>AnimTargetProperty::Translation,"r"=>AnimTargetProperty::Rotation,"s"=>AnimTargetProperty::Scale,"w"=>AnimTargetProperty::Weights,value=>AnimTargetProperty::Custom{name:native::hex_text(value.strip_prefix("c:").ok_or("invalid Semio native target property")?,control)?}};let target=AnimTarget{node,property};let tag=match interpolation_fields{"l"=>0,"s"=>1,"c"=>2,_=>return Err("invalid Semio native interpolation".into())};let interpolation=interpolation(tag)?;let mut keyframe_items=native::Items::new(keyframe_fields)?;let count=keyframe_items.count(control,limits.max_rows)?;native::entities(&mut entities,count,limits)?;let mut keyframes=control.allocate_vec::<AnimKeyframe>(count)?;
 control.scoped_stage(|control|{control.begin_stage(count)?;while let Some(item)=keyframe_items.next(control)?{let[t,value]=native::record(item,control)?;let t=native::float(t,control)?;let value=value_text(value,control,limits,&mut entities)?;keyframes.push(AnimKeyframe{t,value});control.step()?;}Ok::<_,String>(())})?;channels.push(AnimChannel{target,interpolation,keyframes});control.step()?;}Ok::<_,String>(())})?;timelines.push(AnimTimeline{name,channels});control.step()?;}Ok::<_,String>(())})?;
 Ok(SemioAnimationSnapshot{schema,timelines})
}
